      "inputs": {
        "facts": "evals/fixtures/facts.csv",
        "classification": "evals/fixtures/classification.json",
        "published_notice": "evals/fixtures/published-notice.md"
      },
      "checks": [
        "exit:0",
        {"file": "notice-redline.md", "check": "sections:[\"Summary\",\"Redline\",\"Removed claims\"]"},
        {"file": "notice-redline.md", "check": "contains:\"Sentences: 6 unchanged, 3 changed, 3 added, 1 removed.\""},
        {"file": "notice-redline.md", "check": "contains:\"| removed | Every answer is checked by our billing team. | — |\""},
        {"file": "notice-redline.md", "check": "no_unowned_tbd"},
        {"file": "system-card.md", "check": "contains:\"Published notice redlined: 6 unchanged, 3 changed, 3 added, 1 removed\""}
      ]
    },
    {
      "id": "x-hr-benefits-bot-full-facts",
      "prompt": "Write the user notice for 'Benny', the benefits Q&A assistant at Corvane Insurance. Provider: Corvane HR Technology. Purpose: answer questions about your health and retirement benefits. Data: the 2026 benefits handbook. Not for: medical or financial advice. Limitations: may misread plan details for part-time staff. Oversight: HR advisers review flagged chats daily. Contact: benefits@corvane.example. Last updated: 2026-10-01. It talks to employees directly; no synthetic media, no emotion or biometric features.",
      "expected": [
        "Notice opens 'You are chatting with Benny. It is an AI system, not a person.' and each following sentence uses only the stated facts, one per line",
        "Omits the synthetic, deep fake, emotion and biometric sentences because those facts are no",
        "Art. 50 checklist marks Art. 50(1) interaction as applying (owner Product owner) and the emotion/biometric and deep fake rows as not applicable, with Art. 50(5) at most partial",
