      ]
    },
    {
      "id": "x-readability-check-existing-text",
      "prompt": "Is this AI disclosure readable enough for a general audience? 'This conversational interface leverages sophisticated machine-learning methodologies to facilitate expeditious resolution of account-related enquiries, notwithstanding occasional inaccuracies attributable to probabilistic inference.'",
      "expected": [
        "Assesses it against a Flesch-Kincaid grade ceiling (default 8) and says it is clearly above it",
        "Recommends rewriting the underlying facts in plainer words rather than reworking the notice templates, and shows the template sentences ('It is an AI system, not a person.' etc.)",
        "Does not claim the rewritten version makes the system compliant"
      ]
    },
    {
      "id": "x-voice-agent-emotion",
      "prompt": "Our call-centre voice agent (Lumen Telecom) detects caller frustration from tone of voice to escalate calls. Draft the transparency notice and Art. 50 checklist.",
      "expected": [
        "Includes the emotion-recognition notice sentence because the system infers emotion",
        "Checklist row Art. 50(3) emotion recognition applies, owned by the Privacy officer, status missing or to confirm",
        "Unstated facts (purpose wording, data, limitations, contact) are [TO BE BASELINED — owner: Product owner], and the reply states it is not a legal determination"
      ]
    },
    {
      "id": "x-news-summaries-public-interest",
      "prompt": "We publish AI-written daily summaries of city council meetings on our local news site. No human edits them before posting. What do we have to disclose?",
      "expected": [
        "Checklist row Art. 50(4) public-interest text applies, owned by the Content lead",
        "Notes that whether the human-review/editorial-responsibility exemption applies is not assessed by this skill and is for counsel, while flagging that no human edits them",
        "Gives the notice template sentences with unstated facts as [TO BE BASELINED — owner: Product owner]"
      ]
    },
    {
      "id": "x-tutor-for-teens-grade-6",
      "prompt": "Ed-tech: 'Quill', our homework helper for 12-15 year olds, by Brightpath Learning. Purpose: explain maths steps. Not for: doing graded tests. Contact: help@brightpath.example. Our accessibility standard is reading grade 6. Draft it.",
      "expected": [
        "Uses max_grade 6 as the ceiling, and reports the grade as [TO BE BASELINED — computed by the run] while placeholders remain",
        "Notice sentences use the stated name, provider, purpose, not-for and contact; other facts marked for the Product owner",
        "Explains that a grade above 6 fails the run (exit 1) and the long facts are rewritten"
      ]
    },
    {
      "id": "x-exec-what-must-we-tell-users",
      "prompt": "CPO here. Plain answer please: when our sales copilot goes live to EU customers, what exactly do users need to be told, and who on my team owns each piece?",
      "expected": [
        "Gives the seven-row Art. 50 checklist with owners: Product owner (50(1), 50(5)), Engineering lead (50(2)), Privacy officer (50(3)), Content lead (50(4))",
        "Marks applies as 'to confirm' where the yes/no facts are not stated rather than assuming",
