      ]
    },
    {
      "id": "agent-happy-path",
      "prompt": "Model the monthly API cost for the attached workload, price sheet and model assignment against a 1,000 budget.",
      "expected": [
        "Total 855.00; support-chat 465.00 with caching saving 135.00; what-if fict-small 38.75; utilisation 85.5%"
      ],
      "inputs": {
        "workload": "evals/fixtures/workload.csv",
