// lib/result.ts — typed Result and AppError. Pure; importable from any layer.
export type ErrorCode =
  | "VALIDATION_FAILED" | "AUTH_REQUIRED" | "AUTH_FORBIDDEN" | "NOT_FOUND"
  | "CONFLICT" | "RATE_LIMITED" | "UPSTREAM_FAILED" | "INTERNAL"
  | (string & {}); // domain codes, e.g. "INVOICE_ALREADY_PAID"

export type AppError = {
  code: ErrorCode;
  message: string;
  status: 400 | 401 | 403 | 404 | 409 | 422 | 429 | 500 | 502;
  fieldErrors?: Record<string, string[]>;
  cause?: unknown; // never serialized to the client
};

export type Result<T, E = AppError> = { ok: true; value: T } | { ok: false; error: E };

const STATUS: Record<string, AppError["status"]> = {
  VALIDATION_FAILED: 422, AUTH_REQUIRED: 401, AUTH_FORBIDDEN: 403, NOT_FOUND: 404,
  CONFLICT: 409, RATE_LIMITED: 429, UPSTREAM_FAILED: 502, INTERNAL: 500,
};

export const ok = <T>(value: T): Result<T, never> => ({ ok: true, value });

export function fail<E extends AppError = AppError>(
  code: ErrorCode,
  message: string,
  extra: Partial<Omit<AppError, "code" | "message">> = {},
): Result<never, AppError> {
  return { ok: false, error: { code, message, status: extra.status ?? STATUS[code] ?? 400, ...extra } };
}

export const isOk = <T, E>(r: Result<T, E>): r is { ok: true; value: T } => r.ok;

export function unwrapOr<T, E>(r: Result<T, E>, fallback: T): T {
  return r.ok ? r.value : fallback;
}

export function mapResult<T, U, E>(r: Result<T, E>, f: (v: T) => U): Result<U, E> {
  return r.ok ? { ok: true, value: f(r.value) } : r;
}

/** Shape returned from server actions to client components. `cause` is stripped. */
export type ActionState<T = undefined> =
  | { ok: true; data: T }
  | { ok: false; error: { code: ErrorCode; message: string; fieldErrors?: Record<string, string[]> } }
  | { ok: null }; // initial

export function toActionState<T>(r: Result<T, AppError>): ActionState<T> {
  if (r.ok) return { ok: true, data: r.value };
  const { code, message, fieldErrors } = r.error;
  return { ok: false, error: { code, message, fieldErrors } };
}

// server/actions/invoice.ts — thin: parse → auth → service → map → revalidate.
"use server";
import { revalidateTag } from "next/cache";
import { createInvoiceSchema } from "@/server/validators/invoice";
import { requireRole } from "@/server/auth";
import * as invoiceService from "@/server/services/invoice.service";
import { fail, toActionState, type ActionState } from "@/lib/result";
import type { InvoiceDto } from "@/server/services/invoice.service";

export async function createInvoiceAction(
  _prev: ActionState<InvoiceDto>,
  formData: FormData,
): Promise<ActionState<InvoiceDto>> {
  // 1. parse
  const parsed = createInvoiceSchema.safeParse(Object.fromEntries(formData));
  if (!parsed.success) {
    return toActionState(fail("VALIDATION_FAILED", "Check the highlighted fields", { fieldErrors: parsed.error.flatten().fieldErrors }));
  }
  // 2. auth (tenant and user come from the session, never from the form)
  const auth = await requireRole("member");
  if (!auth.ok) return toActionState(auth);
  // 3. service
  const result = await invoiceService.createInvoice(auth.value, parsed.data);
  // 4. revalidate scoped by tenant
  if (result.ok) revalidateTag(`invoices:${auth.value.tenantId}`);
  // 5. serializable state
  return toActionState(result);
}

// server/services/invoice.service.ts — business rules; returns Result; no HTTP/React knowledge.
import "server-only";
import { ok, fail, type Result } from "@/lib/result";
import { log } from "@/lib/logger";
import * as invoicesDb from "@/lib/db/invoices";
import { writeAudit } from "@/lib/db/audit";
import type { CreateInvoiceInput } from "@/server/validators/invoice";
import type { SessionUser } from "@/server/auth";

export type InvoiceDto = { id: string; number: string; amountCents: number; status: string; createdAt: string };

export async function createInvoice(user: SessionUser, input: CreateInvoiceInput): Promise<Result<InvoiceDto>> {
  const started = Date.now();
  if (user.role === "viewer") return fail("AUTH_FORBIDDEN", "Viewers cannot create invoices");

  const existing = await invoicesDb.findByNumber(user.tenantId, input.number);
  if (!existing.ok) return existing;
  if (existing.value) return fail("CONFLICT", `Invoice ${input.number} already exists`);

  const inserted = await invoicesDb.insert({ ...input, tenantId: user.tenantId, createdBy: user.id });
  if (!inserted.ok) return inserted;

  await writeAudit({ actor: user.id, tenantId: user.tenantId, entity: "invoice", entityId: inserted.value.id, action: "create", after: inserted.value });
  log.info({ action: "invoice.create", invoiceId: inserted.value.id, durationMs: Date.now() - started }, "invoice created");
  return ok(toDto(inserted.value));
}

function toDto(row: invoicesDb.InvoiceRow): InvoiceDto {
  return { id: row.id, number: row.number, amountCents: row.amount_cents, status: row.status, createdAt: row.created_at };
}

