      ]
    },
    {
      "id": "x-duplicate-slides-cut",
      "prompt": "Our 18-slide architecture review deck for the client CIO (decision: approve target architecture; 30 min) has three slides that repeat the same integration diagram and two agenda slides. Redline it.",
      "expected": [
