        {
          "file": "readout.md",
          "check": "sections:[\"Bottom line\",\"Wave plan\"]"
        }
      ]
    },
    {
      "id": "agent-missing-rates",
      "prompt": "Here is the inventory for Acme; what does the migration cost?",
      "expected": [
        "Asks for rate inputs; never uses list prices from memory"
      ],
      "inputs": {
        "inventory": "evals/fixtures/inventory.csv",
        "client": "Acme"
      },
      "checks": [
        "exit:2",
        "needs_input:rates"
      ]
    },
    {
      "id": "agent-no-prices-no-numbers",
      "prompt": "Rates file has no prices yet — just give me a ballpark TCO number.",
      "expected": [
        "Every cost line and derived total is [TO BE BASELINED — owner: ___]; no ballpark is invented"
      ],
      "inputs": {
        "inventory": "evals/fixtures/inventory.csv",
        "rates": "evals/fixtures/rates-missing-prices.csv",
        "client": "Acme"
      },
      "checks": [
        "exit:0",
        {
          "file": "tco.csv",
          "check": "contains:\"[TO BE BASELINED\""
        },
        {
          "file": "tco-summary.md",
          "check": "contains:\"[TO BE BASELINED\""
        }
      ]
    },
    {
      "id": "agent-mode-existing",
      "prompt": "Score the Acme interface inventory, plan 3 waves and build the TCO from the rate file; readout without the model.",
      "expected": [
        "Bands, waves and TCO computed; readout.md carries Bottom line, Scoring results, Wave plan, TCO, Risks, Next steps with every figure copied from the summaries; payback outside the horizon raised as a risk"
      ],
      "inputs": {
        "inventory": "evals/fixtures/inventory.csv",
        "rates": "evals/fixtures/rates.csv",
        "client": "Acme",
        "waves": "3",
        "draft_only": "true"
      },
      "checks": [
        "exit:0",
        {
          "file": "readout.md",
          "check": "contains:\"- Payback: not within horizon · 3-year net: -169,000 USD\""
