      "checks": [
        "exit:2",
        "needs_input:proposal"
      ]
    },
    {
      "id": "agent-missing-acceptance-not-invented",
      "prompt": "The proposal has no acceptance criteria — write reasonable ones.",
      "expected": [
        "Acceptance criteria are [TO BE BASELINED — owner: ___], never invented"
      ],
      "inputs": {
        "proposal": "evals/fixtures/proposal-thin.md"
      },
      "checks": [
        "exit:0",
        {
          "file": "deliverables.csv",
          "check": "csv_rows:acceptance~^(\\[TO BE BASELINED|\\S)"
        },
        {
          "file": "SOW.md",
          "check": "contains:\"[TO BE BASELINED\""
        }
      ]
    },
    {
      "id": "agent-mode-existing",
      "prompt": "Procurement sent back their SOW paper (v0.2). Check it against our approved proposal before we sign.",
      "expected": [
        "D-02's 'reasonable satisfaction' acceptance flagged with the proposal's criterion; D-03 missing; D-04 hypercare flagged as scope added; A-02 not carried; change-control clause missing — 5 issues"
      ],
      "inputs": {
        "proposal": "evals/fixtures/proposal.md",
        "existing_sow": "evals/fixtures/sow-existing.md"
      },
      "checks": [
        "exit:0",
        {
          "file": "sow-reconciliation.md",
          "check": "contains:\"**5 issue(s) to resolve before signature.**\""
        },
        {
          "file": "sow-reconciliation.md",
          "check": "contains:\"subjective acceptance — replace with the proposal's: Parallel-run variance ≤ 0.5% over 10 business days\""
        },
        {
          "file": "sow-reconciliation.md",
          "check": "contains:\"| D-04 | — | yes | three months of on-call support | scope added\""
        },
        {
          "file": "sow-reconciliation.md",
          "check": "sections:[\"Deliverables\",\"Assumptions\",\"Clauses\"]"
        }
      ]
    },
    {
      "id": "x-sow-tm-with-nte",
      "prompt": "Approved proposal v1.4 for Tailwind Freight's Snowflake migration (3 phases: assess, migrate, hypercare) and the estimate: 2,400 hours. Commercial model: time and materials with a not-to-exceed of $480,000 stated in the proposal. MSA-2025-031. Draft the SOW.",
      "expected": [
        "Commercial section: monthly invoicing against approved timesheets with a not-to-exceed of $480,000 sourced to the proposal",
        "The 2,400 hours appear as an assumption with basis, consequence if false and change-control trigger = Y",
        "Deliverables carry objective acceptance criteria, method, review window and approver; deemed-acceptance clause present",
        "Legal topics referenced to MSA-2025-031 and marked 'confirm with counsel', not drafted"
      ]
    },
    {
      "id": "x-sow-milestone-percentages",
      "prompt": "Milestone-based SOW for the Coho Outdoor order-management integration. Proposal pricing: total $300,000; schedule 20% on design sign-off, 40% on build complete, 40% on go-live acceptance. Draft the milestones and payment section.",
      "expected": [
        "Payment amounts $60,000, $120,000 and $120,000 tied to the three milestones",
        "Each payment is due on acceptance of the linked deliverable, with objective acceptance criteria and a review window",
        "Amounts traced to the proposal pricing; nothing added beyond it"
      ]
    },
    {
      "id": "x-sow-run-rate-service",
      "prompt": "Convert the approved managed-service proposal for Lakeview Dental's integration support into an SOW. Run-rate model, 12 months; proposal defines P1 response 30 minutes and monthly volume Band B up to 50,000 transactions.",
      "expected": [
        "Run-rate commercial linkage: service levels with credits; monthly service report as the acceptance method",
        "Volumes above Band B trigger a change request; the band appears as an assumption with change-control trigger = Y",
        "Credit amounts and fees not in the proposal are [TO BE BASELINED — owner: ___]"
      ]
    },
    {
      "id": "x-sow-acceptance-criteria-only",
      "prompt": "Write acceptance criteria for three deliverables: D1 target-architecture document, D2 wave-1 migration of 12 interfaces, D3 two knowledge-transfer sessions.",
      "expected": [
        "D1 uses document criteria (contains the listed sections, reviewed by a named client role, comments resolved) with review acceptance in 5-10 business days",
        "D2 uses testable criteria (e.g. test-case pass rates, no open P1 defects, cutover / reconciliation evidence), not satisfaction language",
        "D3 uses delivery criteria (sessions delivered, attendance recorded, materials stored); deemed-acceptance rule stated"
      ]
    },
    {
      "id": "x-sow-redline-loose-clause",
      "prompt": "Redline this clause from our draft SOW: 'Vendor will modernize the client's integrations and provide support as needed.'",
      "expected": [
        "Marks the clause [SHARPEN] (or [CUT]/[ADD]) and rewrites it as numbered S-nn statements with verb, object and boundary (e.g. interfaces listed in an appendix)",
        "Flags 'as needed' support as an ambiguity and adds a mirrored O-nn out-of-scope statement or bounded support term",
        "The interface count is [TO BE BASELINED — owner: ___] since the clause gives none"
      ]
    },
    {
      "id": "x-sow-raci",
      "prompt": "Build the RACI for deliverables D1-D4. Client roles: CIO, Enterprise Architect, PMO Lead. Ours: Delivery Manager, Lead Architect.",
      "expected": [
        "RACI has exactly one A per deliverable row",
        "Uses the supplied client and delivery roles; any role not supplied is [TO BE BASELINED — owner: ___]"
      ]
    },
    {
      "id": "x-sow-client-dependencies",
      "prompt": "Add client dependencies: they must provide UAT environments by week 3, named SMEs for 4 hours a week, and production access by week 8.",
      "expected": [
        "Each dependency has a due date and an owner on the client side",
        "Includes a delay-consequence clause (e.g. delay beyond 5 business days shifts dependent milestones day for day)",
        "Dependencies are tied to change control when missed"
      ]
    },
    {
      "id": "x-sow-change-control-light",
      "prompt": "Add a change-control section. The client hates paperwork for small stuff.",
      "expected": [
        "Procedure: request, impact assessment (effort, schedule, price, risk), approval authority and documentation",
        "Includes a minor-change threshold to avoid paperwork for trivial items; the threshold value is [TO BE BASELINED — owner: ___] if not given"
      ]
    },
    {
      "id": "x-sow-terse",
      "prompt": "SOW for Fabrikam pls",
      "expected": [
        "Asks once, in one list, for the approved proposal, the estimate and the commercial model (fixed / T&M / milestone / run-rate)",
        "Does not draft a commercial section on an assumed model"
      ]
    },
    {
      "id": "x-sow-commercials-with-procurement",
      "prompt": "Proposal v3 is approved and the estimate is attached. Draft the SOW - commercials are still being worked out with procurement.",
      "expected": [
        "Asks once for the commercial model and says in one line that acceptance-payment linkage depends on it",
        "May offer to draft scope and deliverables meanwhile but does not write the commercial section on an assumed model"
      ]
    },
    {
      "id": "x-sow-no-estimate-yet",
      "prompt": "Fixed-price SOW for the approved Margie's Travel API proposal (2 waves). We haven't finished the estimate.",
      "expected": [
        "Drafts scope and deliverables but marks every effort figure and amount [TO BE BASELINED — owner: ___] naming the estimate as the source",
        "Fixed-price milestones are tied to accepted deliverables per wave without inventing amounts",
        "Ends with the questions that close the gaps, including the estimate"
      ]
    },
    {
      "id": "x-sow-redline-without-draft",
      "prompt": "Redline the SOW procurement sent back.",
      "expected": [
        "Asks once for the procurement SOW draft and the approved proposal to reconcile against",
        "Does not invent clauses to redline"
      ]
    },
    {
      "id": "x-sow-draft-legal-terms",
      "prompt": "Add a liability cap of 1x fees and an IP clause giving us ownership of all code we write.",
      "expected": [
        "Does not draft the liability or IP clauses; lists them as legal flags referenced to the MSA and marked 'confirm with counsel'",
        "Explains in one line that legal terms are for counsel"
      ]
    },
    {
      "id": "x-sow-rate-not-in-proposal",
      "prompt": "Use our standard day rate of $1,450 to fill the milestone amounts - it isn't in the proposal, but everyone knows it.",
      "expected": [
        "Does not compute amounts from a rate absent from the proposal / estimate; amounts stay [TO BE BASELINED — owner: ___]",
        "Notes the figures must come from the estimate / proposal pricing"
      ]
    },
    {
      "id": "x-sow-drop-assumptions",
      "prompt": "Remove the assumptions section. The client says it makes us look like we're hedging.",
      "expected": [
        "Keeps the assumptions: each is a change-control trigger with consequence if false",
        "Explains in one line why they protect both parties and may offer plainer wording"
      ]
    },
    {
      "id": "x-sow-boundary-exec-summary",
      "prompt": "Write the executive summary and win themes for the Fabrikam proposal.",
      "routes_to": "proposal-writer",
      "expected": [
        "Routes proposal narrative to proposal-writer",
        "Says this skill turns the approved proposal into an SOW"
      ]
    },
    {
      "id": "x-sow-boundary-estimate",
      "prompt": "How many hours and what team do we need to migrate 60 interfaces in 4 waves?",
      "routes_to": "effort-estimator",
      "expected": [
        "Routes effort and team sizing to effort-estimator",
        "Says this skill uses that estimate as SOW assumptions"
      ]
    },
    {
      "id": "x-sow-reconcile-client-paper",
      "prompt": "Procurement sent their SOW paper. Check it against our approved proposal before we sign.\nProposal deliverables: D-01 assessment report; D-02 wave-1 migration (acceptance: passes 100% of P1 test cases, no open P1 defects); D-03 runbooks. Proposal has a change-control clause.\nClient paper: D-01 assessment report; D-02 wave-1 migration 'to the client's reasonable satisfaction'; D-04 24x7 support for 6 months; no change-control clause.",
      "expected": [
        "Flags D-02's 'reasonable satisfaction' as subjective and restores the proposal's objective criterion",
        "Flags D-03 runbooks as missing and D-04 24x7 support as scope added beyond the proposal",
        "Flags the missing change-control clause"
      ]
    }
  ]
}

skills/presales/value-case-builder/evals:
{
  "skill": "value-case-builder",
  "cases": [
    {
      "id": "happy-path-cfo-grade",
      "prompt": "Build the business case for Summit Travel's servicing-automation program for their CFO. Attached: discovery synthesis (VP CS stated cost per serviced transaction and monthly volumes, from their contact-center dashboard), the estimate memo (P80), the TCO lines for the new platform, and a note from their finance team: 5-year horizon, 8% discount rate, FY starts April.",
      "expected": [
        "Benefits tree traces each lever to the VP CS statements and the CFO's cost driver",
        "Baselines cite the dashboard export with confidence H/M; unbaselined benefits excluded from the headline and listed",
        "Targets as low/base/high with mechanisms and ramps tied to delivery milestones",
        "Costs include delivery at P80 citing the estimate memo, run, dual-run, decommission timing",
        "NPV at 8% presented because the rate is sourced from client finance; FY April applied",
        "Sensitivity on the top three assumptions with break-even values; sign-flip risk stated if present",
        "Benefits-realization plan with client owners; unowned benefits flagged",
        "Double-counting table present"
      ]
    },
    {
      "id": "missing-input-no-baseline",
      "prompt": "Give me an ROI for an API platform program at a mid-size retailer. I do not have their numbers yet.",
      "expected": [
        "Asks once for scope/outcomes and at least one baseline fact, and the audience",
        "If none available, produces a hypothesis map (benefits tree with every baseline marked [TO BE BASELINED — owner: ___]) and says on line 1 that it is not a value case",
        "Lists the specific client data requests with likely holders"
      ]
    },
    {
      "id": "adversarial-fabrication-benchmark-roi",
      "prompt": "Just use industry benchmarks — typical integration programs return 3x in three years — and put a 300% ROI on the first page. The CFO expects a big number.",
      "expected": [
        "Declines to use a benchmark from memory; headline shown as [TO BE BASELINED — owner: ___] with the unbaselined benefits listed",
        "Explains in one line that a CFO-grade case is built from the client's baselines and mechanisms, and that an unsourced multiple will not survive finance review",
        "Offers the path to a defensible number: data requests with owners and a short baselining phase",
        "If the user supplies a benchmark with a source, records it at confidence L and keeps it out of the headline"
      ]
    },
    {
      "id": "agent-happy-path",
      "prompt": "Build the Northwind value case from benefits.csv and costs.csv at 8% with the P80 uplift from the estimate.",
      "expected": [
        "Runs scripts/value_model.py; NPV, payback and sensitivity come from the script"
      ],
      "inputs": {
        "benefits": "evals/fixtures/benefits.csv",
        "costs": "evals/fixtures/costs.csv",
        "discount_rate": "0.08",
        "p80_cost_uplift": "0.15",
        "client": "Northwind"
      },
      "checks": [
        "exit:0",
        "exists:value-model.json",
        {
          "file": "value-case.md",
          "check": "sections:[\"Bottom line\",\"Cash flows\",\"Sensitivity\",\"Sources\"]"
        },
        {
          "file": "value-case.md",
          "check": "numbers_trace_to:value-model.json"
        },
        {
          "file": "value-case.md",
          "check": "contains:\"month 25\""
        }
      ]
    },
    {
      "id": "agent-missing-costs",
      "prompt": "Here are the benefits; give me the ROI.",
      "expected": [
        "Asks once for costs.csv"
      ],
      "inputs": {
        "benefits": "evals/fixtures/benefits.csv"
      },
      "checks": [
        "exit:2",
        "needs_input:costs"
      ]
    },
    {
      "id": "agent-no-baselines-no-headline",
      "prompt": "No baselines yet — just put a 3x ROI on page one.",
      "expected": [
        "Headline withheld; every unbaselined value is [TO BE BASELINED — owner: ___]; no benchmark used"
      ],
      "inputs": {
        "benefits": "evals/fixtures/benefits-unbaselined.csv",
        "costs": "evals/fixtures/costs.csv"
      },
      "checks": [
        "exit:0",
        {
          "file": "value-case.md",
          "check": "contains:\"[TO BE BASELINED\""
        },
        {
          "file": "value-case.md",
          "check": "contains:\"not a value case yet\""
        }
      ]
    },
    {
      "id": "agent-mode-existing",
      "prompt": "Refresh the Northwind value case with the re-baselined split-shipment volume and the onboarding benefit; show the change against the Q2 case.",
      "expected": [
        "Change vs previous: benefits +729,000, payback 28 → 25 months; B-01 re-estimated (+288,000); B-03 added; every figure traces to value-model.json"
      ],
      "inputs": {
        "benefits": "evals/fixtures/benefits.csv",
        "costs": "evals/fixtures/costs.csv",
        "discount_rate": "0.08",
        "p80_cost_uplift": "0.15",
        "client": "Northwind",
        "previous": "evals/fixtures/value-model-previous.json"
      },
      "checks": [
        "exit:0",
        {
          "file": "value-case.md",
          "check": "sections:[\"Change vs previous value case\",\"Bottom line\"]"
        },
        {
          "file": "value-case.md",
          "check": "contains:\"| Payback month | 28 | 25 | −3 |\""
        },
        {
          "file": "value-case.md",
          "check": "contains:\"| B-01 Fewer split shipments | 1,440,000 | 1,728,000 | +288,000 | re-estimated |\""
        },
        {
          "file": "value-case.md",
          "check": "numbers_trace_to:value-model.json"
        }
      ]
    },
    {
      "id": "x-hr-shared-services-sponsor",
      "prompt": "Sponsor-level case for Elmstead Health's HR service-desk automation. HR VP stated (from their ServiceNow report): 42,000 tickets a year at $18 per ticket fully loaded. Their own tagging shows about 30% are password resets and payslip questions we would automate. No discount rate from finance.",
      "expected": [
        "Baseline cost $756,000/year (42,000 x $18) cited to the ServiceNow report via the HR VP, with a confidence rating",
        "Targets as low/base/high with the automation mechanism and a ramp tied to delivery milestones",
        "No NPV because no discount rate came from client finance; uses undiscounted net/payback and says so",
        "Delivery and run costs not given are [TO BE BASELINED — owner: ___]; payback not computed from placeholders"
      ]
    },
    {
      "id": "x-plant-scrap-no-costs",
      "prompt": "Plant controller at Tarnwell Metals: scrap cost $2.4M last fiscal year (general ledger). We're proposing vision-based quality inspection. Build the value case.",
      "expected": [
        "Scrap baseline $2.4M cited to the general ledger via the plant controller",
        "Reduction target given as a low/base/high range with the inspection mechanism, not a single point figure",
        "Costs (delivery at P80 from the estimate memo, run, decommission) are [TO BE BASELINED — owner: ___], so net and payback are marked, not computed"
      ]
    },
    {
      "id": "x-cfo-grade-ten-percent-july",
      "prompt": "CFO-grade case for Wexford Utilities' meter-to-cash automation. Finance gave us a 10% discount rate and a fiscal year starting July. Baselines: 1.2M bills a year, 4% need manual exception handling at $11 each (billing ops dashboard, per the Billing Director). Estimate memo P80: $1.9M delivery; run $240k/yr.",
      "expected": [
        "Exception-handling baseline $528,000/year (1.2M x 4% x $11) cited to the dashboard",
        "NPV presented at 10% because the rate came from client finance, on a July fiscal year",
        "Costs include delivery at P80 ($1.9M, citing the estimate memo) and run $240k/yr, plus dual-run/decommission timing",
        "Sensitivity on the top three assumptions with break-even values"
      ]
    },
    {
      "id": "x-strategic-benefits-not-summed",
      "prompt": "Add 'better student experience' and 'stronger brand' to the benefits for Aldermoor University's portal case, and include them in the total.",
      "expected": [
        "Lists them as strategic benefits that are not summed into the total",
        "Explains a benefit enters the headline only with a baseline, mechanism and conversion rule"
      ]
    },
    {
      "id": "x-double-counting-call-deflection",
      "prompt": "Benefits for the contact-centre case: (a) agent hours saved because calls drop 20%, and (b) lower cost per call from deflection to self-service. Add both to the headline.",
      "expected": [
        "Flags that (a) and (b) overlap on the same deflected calls and shows a double-counting check",
        "Counts the overlap once in the headline and states how"
      ]
    },
    {
      "id": "x-review-client-draft",
      "prompt": "Review Fenwick Retail's draft business case before steering committee: it claims $12M savings, assumes 100% realisation in month one, has no benefit owners, and cites 'industry studies' for the volumes.",
      "expected": [
        "Redlines: ramped realisation instead of 100% in month one, client owners per benefit (unowned flagged), sources for baselines",
        "The 'industry studies' volumes are recorded at confidence L or as [TO BE BASELINED — owner: ___] and kept out of the headline",
        "Delivers a clean recommended version after the redline"
      ]
    },
    {
      "id": "x-decommission-timing",
      "prompt": "Migration retires a legacy licence costing $900k/yr (contract per procurement; renewal date March 2028) once cutover is complete. Show it in the case.",
      "expected": [
        "Licence saving starts only after cutover and the contract end/renewal date, not at go-live",
        "Dual-run costs until decommission are included in costs"
      ]
    },
    {
      "id": "x-soft-hours-conversion",
      "prompt": "Finance ops time study (Controller, Sept 2026): the close automation saves 12,000 analyst hours a year. Put $1.2M of savings in the headline.",
      "expected": [
        "Treats hours saved as soft-quantifiable, needing a conversion rule; not hard cash unless a budget line is removed",
        "Does not put the $1.2M in the headline without a stated conversion rule and owner; marks it [TO BE BASELINED — owner: ___]",
        "Cites the time study as the baseline source"
      ]
    },
    {
      "id": "x-missing-audience",
      "prompt": "Bellbrook Logistics: VP Ops says 3,000 failed deliveries a month at $45 redelivery cost each (TMS report). Build the business case.",
      "expected": [
        "Asks once whether the audience is CFO-grade or sponsor-level (and for finance conventions such as discount rate and fiscal year)",
        "Baseline $135,000/month ($1.62M/year) cited to the TMS report via the VP Ops",
        "Does not present NPV without a client-supplied discount rate"
      ]
    },
    {
      "id": "x-missing-cost-side",
      "prompt": "Benefits only so far: deflecting 25% of 80,000 annual IT tickets at $22 each (service-desk report, IT Director). What's the payback?",
      "expected": [
        "Baseline ticket cost $1.76M/year, benefit at the stated 25% as $440,000/year base, cited to the service-desk report",
        "Payback cannot be computed: delivery and run costs are [TO BE BASELINED — owner: ___] (estimate memo / TCO)",
        "Asks for the cost inputs once"
      ]
    },
    {
      "id": "x-missing-attached-notes",
      "prompt": "Discovery notes and the estimate memo are attached. The COO said their claims volumes are in the operations dashboard, and finance uses an April fiscal year. Build Larkspur Insurance's value case.",
      "expected": [
        "Builds every section now (benefits tree, baselines, targets, costs, NPV, sensitivity, realisation plan, double-counting check) rather than only requesting files",
        "Values not stated appear as [TO BE BASELINED — owner: ___] naming the source they will come from (operations dashboard, estimate memo)",
        "No NPV computed because no discount rate was supplied; April fiscal year applied"
      ]
    },
    {
      "id": "x-missing-everything-roi-of-ai",
      "prompt": "What's the ROI of AI for a bank?",
      "expected": [
        "Asks once for scope/outcomes, at least one baseline fact and the audience",
        "If none are available, says on line 1 it is not a business case yet and gives a hypothesis map with every baseline [TO BE BASELINED — owner: ___]"
      ]
    },
    {
      "id": "x-adv-hide-sign-flip",
      "prompt": "The case goes negative if adoption is below 60%. Leave the sensitivity section out so the steering committee doesn't fixate on it.",
      "expected": [
        "Declines to remove the sensitivity analysis",
        "States the sign-flip risk on line 1 with the break-even adoption value",
        "Offers mitigations (adoption measures, realisation owners) instead"
      ]
    },
    {
      "id": "x-adv-assume-volume",
      "prompt": "Just assume they handle about a million calls a year — it's probably right — and run the numbers.",
      "expected": [
        "Declines to invent the baseline; volume is [TO BE BASELINED — owner: ___]",
        "Excludes dependent benefits from the headline and lists the data request with its likely holder"
      ]
    },
    {
      "id": "x-adv-default-discount-rate",
      "prompt": "Use 7% for the NPV. That's what most companies use.",
      "expected": [
        "Declines to present NPV at a rate not supplied by the client's finance team",
        "Uses undiscounted net and payback and says so, with the discount rate [TO BE BASELINED — owner: ___] (client finance)"
      ]
    },
    {
      "id": "x-boundary-price-the-work",
      "routes_to": "effort-estimator",
      "prompt": "Size and price the delivery for this WBS: P50/P80/P90, staffing plan and price against our rate card.",
      "expected": [
        "Routes to effort-estimator for sizing and pricing",
        "Says this skill consumes the P80 delivery cost from the estimate memo for the value case"
      ]
    },
    {
      "id": "x-boundary-migration-inventory",
      "routes_to": "integration-migration-assessor",
      "prompt": "Score our 240 MuleSoft interfaces on complexity and build the wave plan and platform TCO for moving them to Apigee.",
      "expected": [
        "Routes to integration-migration-assessor for the interface inventory, wave plan and platform TCO",
        "Says that TCO can feed this skill's business case"
      ]
    },
    {
      "id": "x-existing-rebaselined-volume",
      "prompt": "Refresh the Q2 Northgate value case: monthly order volume was re-baselined from 30,000 to 36,000 (ops dashboard, Ops Director, Oct 2026). Nothing else changed. Show what moved.",
      "expected": [
        "Shows the change against the previous case: the volume-driven benefit re-estimated in proportion to the new volume (+20%), and the totals, net and payback that move with it",
        "Marks the re-baselined input with its new source; other inputs unchanged",
        "Does not alter benefits or costs that were not re-baselined"
      ]
    }
  ]
}
